@import url("chrome://messenger/skin/shared/tabmail.css");

@media (prefers-contrast) {
  #tabmail {
    background-color: ActiveCaption;

    &:-moz-window-inactive {
      background-color: InactiveCaption;
    }
  }
}

/**
 * Tabmail Tabs
 */

#tabpanelcontainer {
  appearance: none;
  color-scheme: light dark;

  :root[lwtheme] & {
    color: inherit;
  }
}

